// Package notes holds the note model, its validation rules and a SQLite-backed store.
package notes

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"slices"
	"strings"
	"unicode/utf8"
)

const (
	MaxTitleLen = 200
	MaxTagLen   = 32
)

// Note is a stored note.
type Note struct {
	ID    int64    `json:"id"`
	Title string   `json:"title"`
	Body  string   `json:"body"`
	Tags  []string `json:"tags"`
}

// Input is the validated content of a note as supplied by a client.
type Input struct {
	Title string
	Body  string
	Tags  []string
}

// ValidationError describes why client input was rejected.
type ValidationError struct{ Msg string }

func (e *ValidationError) Error() string { return e.Msg }

func invalid(format string, args ...any) error {
	return &ValidationError{Msg: fmt.Sprintf(format, args...)}
}

// ParseInput decodes and validates a JSON note payload. Errors are *ValidationError.
func ParseInput(data []byte) (Input, error) {
	var fields map[string]json.RawMessage
	dec := json.NewDecoder(bytes.NewReader(data))
	if err := dec.Decode(&fields); err != nil || fields == nil {
		return Input{}, invalid("request body must be a JSON object")
	}
	if _, err := dec.Token(); !errors.Is(err, io.EOF) {
		return Input{}, invalid("request body must be a single JSON object")
	}

	var in Input
	raw, ok := fields["title"]
	if !ok {
		return Input{}, invalid("title is required")
	}
	if !decodeString(raw, &in.Title) {
		return Input{}, invalid("title must be a string")
	}
	in.Title = strings.TrimSpace(in.Title)
	if n := utf8.RuneCountInString(in.Title); n < 1 || n > MaxTitleLen {
		return Input{}, invalid("title must be 1-%d characters", MaxTitleLen)
	}

	if raw, ok := fields["body"]; ok && !decodeString(raw, &in.Body) {
		return Input{}, invalid("body must be a string")
	}

	in.Tags = []string{}
	if raw, ok := fields["tags"]; ok {
		tags, err := parseTags(raw)
		if err != nil {
			return Input{}, err
		}
		in.Tags = tags
	}
	return in, nil
}

// decodeString decodes raw into s, rejecting anything but a JSON string (including null).
func decodeString(raw json.RawMessage, s *string) bool {
	raw = bytes.TrimSpace(raw)
	if len(raw) == 0 || raw[0] != '"' {
		return false
	}
	return json.Unmarshal(raw, s) == nil
}

func parseTags(raw json.RawMessage) ([]string, error) {
	raw = bytes.TrimSpace(raw)
	if len(raw) == 0 || raw[0] != '[' {
		return nil, invalid("tags must be an array of strings")
	}
	var items []json.RawMessage
	if err := json.Unmarshal(raw, &items); err != nil {
		return nil, invalid("tags must be an array of strings")
	}
	tags := make([]string, 0, len(items))
	for _, item := range items {
		var tag string
		if !decodeString(item, &tag) {
			return nil, invalid("tags must be an array of strings")
		}
		if !ValidTag(tag) {
			return nil, invalid("invalid tag %q: must be 1-%d characters from a-z, 0-9 and -", tag, MaxTagLen)
		}
		tags = append(tags, tag)
	}
	slices.Sort(tags)
	return slices.Compact(tags), nil
}

// ValidTag reports whether tag is 1-32 characters from a-z, 0-9 and '-'.
func ValidTag(tag string) bool {
	if len(tag) < 1 || len(tag) > MaxTagLen {
		return false
	}
	for i := 0; i < len(tag); i++ {
		c := tag[i]
		if !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '-') {
			return false
		}
	}
	return true
}

package notes

import (
	"errors"
	"slices"
	"strings"
	"testing"
)

func TestParseInput(t *testing.T) {
	tests := []struct {
		name    string
		body    string
		want    Input
		wantErr bool
	}{
		{name: "minimal", body: `{"title":"x"}`, want: Input{Title: "x", Tags: []string{}}},
		{name: "trimmed", body: `{"title":"  hi  ","body":"b"}`, want: Input{Title: "hi", Body: "b", Tags: []string{}}},
		{name: "tags sorted and deduplicated", body: `{"title":"x","tags":["b","a-1","b"]}`, want: Input{Title: "x", Tags: []string{"a-1", "b"}}},
		{name: "max title", body: `{"title":"` + strings.Repeat("é", 200) + `"}`, want: Input{Title: strings.Repeat("é", 200), Tags: []string{}}},
		{name: "title too long", body: `{"title":"` + strings.Repeat("a", 201) + `"}`, wantErr: true},
		{name: "blank title", body: `{"title":"   "}`, wantErr: true},
		{name: "missing title", body: `{}`, wantErr: true},
		{name: "null title", body: `{"title":null}`, wantErr: true},
		{name: "numeric title", body: `{"title":1}`, wantErr: true},
		{name: "array", body: `[]`, wantErr: true},
		{name: "null", body: `null`, wantErr: true},
		{name: "truncated", body: `{"title": `, wantErr: true},
		{name: "trailing garbage", body: `{"title":"x"} x`, wantErr: true},
		{name: "body not string", body: `{"title":"x","body":3}`, wantErr: true},
		{name: "body null", body: `{"title":"x","body":null}`, wantErr: true},
		{name: "tags not array", body: `{"title":"x","tags":"a"}`, wantErr: true},
		{name: "tag not string", body: `{"title":"x","tags":[1]}`, wantErr: true},
		{name: "tag uppercase", body: `{"title":"x","tags":["Bad"]}`, wantErr: true},
		{name: "tag empty", body: `{"title":"x","tags":[""]}`, wantErr: true},
		{name: "tag too long", body: `{"title":"x","tags":["` + strings.Repeat("a", 33) + `"]}`, wantErr: true},
		{name: "tag max length", body: `{"title":"x","tags":["` + strings.Repeat("a", 32) + `"]}`, want: Input{Title: "x", Tags: []string{strings.Repeat("a", 32)}}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := ParseInput([]byte(tt.body))
			if tt.wantErr {
				var ve *ValidationError
				if !errors.As(err, &ve) {
					t.Fatalf("want ValidationError, got %v (input %+v)", err, got)
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if got.Title != tt.want.Title || got.Body != tt.want.Body || !slices.Equal(got.Tags, tt.want.Tags) || got.Tags == nil {
				t.Fatalf("got %+v, want %+v", got, tt.want)
			}
		})
	}
}

package notes

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"net/url"
	"strings"

	_ "modernc.org/sqlite" // registers the "sqlite" driver
)

// ErrNotFound is returned when a note does not exist.
var ErrNotFound = errors.New("note not found")

const schema = `
CREATE TABLE IF NOT EXISTS notes (
	id    INTEGER PRIMARY KEY AUTOINCREMENT,
	title TEXT NOT NULL,
	body  TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS note_tags (
	note_id INTEGER NOT NULL REFERENCES notes(id) ON DELETE CASCADE,
	tag     TEXT NOT NULL,
	PRIMARY KEY (note_id, tag)
) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS note_tags_by_tag ON note_tags(tag, note_id);
`

// Store persists notes in a SQLite database.
type Store struct {
	db *sql.DB
}

// Open opens (creating if needed) the SQLite database at path and ensures the schema exists.
func Open(ctx context.Context, path string) (*Store, error) {
	q := url.Values{}
	for _, p := range []string{"foreign_keys(1)", "busy_timeout(5000)", "journal_mode(WAL)", "synchronous(NORMAL)"} {
		q.Add("_pragma", p)
	}
	dsn := (&url.URL{Scheme: "file", OmitHost: true, Path: path, RawQuery: q.Encode()}).String()
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, fmt.Errorf("open database: %w", err)
	}
	// SQLite allows a single writer; one shared connection serializes access
	// without SQLITE_BUSY errors while database/sql queues concurrent callers.
	db.SetMaxOpenConns(1)
	if _, err := db.ExecContext(ctx, schema); err != nil {
		db.Close()
		return nil, fmt.Errorf("create schema: %w", err)
	}
	return &Store{db: db}, nil
}

// Close closes the underlying database.
func (s *Store) Close() error { return s.db.Close() }

// Create stores a new note and returns it.
func (s *Store) Create(ctx context.Context, in Input) (Note, error) {
	var id int64
	err := s.inTx(ctx, func(tx *sql.Tx) error {
		res, err := tx.ExecContext(ctx, `INSERT INTO notes (title, body) VALUES (?, ?)`, in.Title, in.Body)
		if err != nil {
			return err
		}
		if id, err = res.LastInsertId(); err != nil {
			return err
		}
		return insertTags(ctx, tx, id, in.Tags)
	})
	if err != nil {
		return Note{}, fmt.Errorf("create note: %w", err)
	}
	return Note{ID: id, Title: in.Title, Body: in.Body, Tags: in.Tags}, nil
}

// Get returns the note with the given id or ErrNotFound.
func (s *Store) Get(ctx context.Context, id int64) (Note, error) {
	n := Note{ID: id}
	err := s.db.QueryRowContext(ctx, `SELECT title, body FROM notes WHERE id = ?`, id).Scan(&n.Title, &n.Body)
	if errors.Is(err, sql.ErrNoRows) {
		return Note{}, ErrNotFound
	}
	if err != nil {
		return Note{}, fmt.Errorf("get note: %w", err)
	}
	tags, err := s.tagsFor(ctx, []int64{id})
	if err != nil {
		return Note{}, err
	}
	n.Tags = tags[id]
	if n.Tags == nil {
		n.Tags = []string{}
	}
	return n, nil
}

// Update replaces the content of an existing note or returns ErrNotFound.
func (s *Store) Update(ctx context.Context, id int64, in Input) (Note, error) {
	err := s.inTx(ctx, func(tx *sql.Tx) error {
		res, err := tx.ExecContext(ctx, `UPDATE notes SET title = ?, body = ? WHERE id = ?`, in.Title, in.Body, id)
		if err != nil {
			return err
		}
		if n, err := res.RowsAffected(); err != nil {
			return err
		} else if n == 0 {
			return ErrNotFound
		}
		if _, err := tx.ExecContext(ctx, `DELETE FROM note_tags WHERE note_id = ?`, id); err != nil {
			return err
		}
		return insertTags(ctx, tx, id, in.Tags)
	})
	if errors.Is(err, ErrNotFound) {
		return Note{}, err
	}
	if err != nil {
		return Note{}, fmt.Errorf("update note: %w", err)
	}
	return Note{ID: id, Title: in.Title, Body: in.Body, Tags: in.Tags}, nil
}

// Delete removes a note or returns ErrNotFound.
func (s *Store) Delete(ctx context.Context, id int64) error {
	res, err := s.db.ExecContext(ctx, `DELETE FROM notes WHERE id = ?`, id)
	if err != nil {
		return fmt.Errorf("delete note: %w", err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return fmt.Errorf("delete note: %w", err)
	}
	if n == 0 {
		return ErrNotFound
	}
	return nil
}

// Filter selects notes in List. Zero values mean "no constraint", except Limit which must be positive.
type Filter struct {
	Tag   string
	Query string
	After int64
	Limit int
}

// List returns notes matching f, ordered by id ascending.
func (s *Store) List(ctx context.Context, f Filter) ([]Note, error) {
	var (
		where []string
		args  []any
	)
	if f.Tag != "" {
		where = append(where, `EXISTS (SELECT 1 FROM note_tags t WHERE t.note_id = n.id AND t.tag = ?)`)
		args = append(args, f.Tag)
	}
	if f.Query != "" {
		// SQLite's built-in lower() folds ASCII letters only, which is exactly the required matching.
		where = append(where, `(instr(lower(n.title), lower(?)) > 0 OR instr(lower(n.body), lower(?)) > 0)`)
		args = append(args, f.Query, f.Query)
	}
	where = append(where, `n.id > ?`)
	args = append(args, f.After)

	query := `SELECT n.id, n.title, n.body FROM notes n WHERE ` + strings.Join(where, " AND ") + ` ORDER BY n.id LIMIT ?`
	args = append(args, f.Limit)

	rows, err := s.db.QueryContext(ctx, query, args...)
	if err != nil {
		return nil, fmt.Errorf("list notes: %w", err)
	}
	defer rows.Close()

	list := []Note{}
	var ids []int64
	for rows.Next() {
		var n Note
		if err := rows.Scan(&n.ID, &n.Title, &n.Body); err != nil {
			return nil, fmt.Errorf("list notes: %w", err)
		}
		list = append(list, n)
		ids = append(ids, n.ID)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("list notes: %w", err)
	}
	rows.Close()

	tags, err := s.tagsFor(ctx, ids)
	if err != nil {
		return nil, err
	}
	for i := range list {
		list[i].Tags = tags[list[i].ID]
		if list[i].Tags == nil {
			list[i].Tags = []string{}
		}
	}
	return list, nil
}

// TagCount is the number of notes carrying a tag.
type TagCount struct {
	Tag   string `json:"tag"`
	Count int64  `json:"count"`
}

// TagCounts returns every tag in use, ordered by count descending, then tag ascending.
func (s *Store) TagCounts(ctx context.Context) ([]TagCount, error) {
	rows, err := s.db.QueryContext(ctx,
		`SELECT tag, COUNT(*) AS c FROM note_tags GROUP BY tag ORDER BY c DESC, tag ASC`)
	if err != nil {
		return nil, fmt.Errorf("count tags: %w", err)
	}
	defer rows.Close()
	counts := []TagCount{}
	for rows.Next() {
		var tc TagCount
		if err := rows.Scan(&tc.Tag, &tc.Count); err != nil {
			return nil, fmt.Errorf("count tags: %w", err)
		}
		counts = append(counts, tc)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("count tags: %w", err)
	}
	return counts, nil
}

// Count returns the number of stored notes.
func (s *Store) Count(ctx context.Context) (int64, error) {
	var n int64
	if err := s.db.QueryRowContext(ctx, `SELECT COUNT(*) FROM notes`).Scan(&n); err != nil {
		return 0, fmt.Errorf("count notes: %w", err)
	}
	return n, nil
}

func (s *Store) tagsFor(ctx context.Context, ids []int64) (map[int64][]string, error) {
	out := make(map[int64][]string, len(ids))
	if len(ids) == 0 {
		return out, nil
	}
	args := make([]any, len(ids))
	for i, id := range ids {
		args[i] = id
	}
	placeholders := strings.TrimSuffix(strings.Repeat("?,", len(ids)), ",")
	rows, err := s.db.QueryContext(ctx,
		`SELECT note_id, tag FROM note_tags WHERE note_id IN (`+placeholders+`) ORDER BY note_id, tag`, args...)
	if err != nil {
		return nil, fmt.Errorf("load tags: %w", err)
	}
	defer rows.Close()
	for rows.Next() {
		var (
			id  int64
			tag string
		)
		if err := rows.Scan(&id, &tag); err != nil {
			return nil, fmt.Errorf("load tags: %w", err)
		}
		out[id] = append(out[id], tag)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("load tags: %w", err)
	}
	return out, nil
}

func insertTags(ctx context.Context, tx *sql.Tx, id int64, tags []string) error {
	if len(tags) == 0 {
		return nil
	}
	stmt, err := tx.PrepareContext(ctx, `INSERT INTO note_tags (note_id, tag) VALUES (?, ?)`)
	if err != nil {
		return err
	}
	defer stmt.Close()
	for _, tag := range tags {
		if _, err := stmt.ExecContext(ctx, id, tag); err != nil {
			return err
		}
	}
	return nil
}

func (s *Store) inTx(ctx context.Context, fn func(*sql.Tx) error) error {
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	if err := fn(tx); err != nil {
		tx.Rollback()
		return err
	}
	return tx.Commit()
}

package notes

import (
	"context"
	"errors"
	"os"
	"path/filepath"
	"testing"
)

func openTestStore(t *testing.T, path string) *Store {
	t.Helper()
	s, err := Open(context.Background(), path)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { s.Close() })
	return s
}

func TestIDsNotReusedAcrossReopen(t *testing.T) {
	ctx := context.Background()
	path := filepath.Join(t.TempDir(), "dir with space?", "notes.db")
	if err := mkdirAll(filepath.Dir(path)); err != nil {
		t.Fatal(err)
	}
	s := openTestStore(t, path)
	for range 2 {
		if _, err := s.Create(ctx, Input{Title: "t", Tags: []string{"a"}}); err != nil {
			t.Fatal(err)
		}
	}
	if err := s.Delete(ctx, 2); err != nil {
		t.Fatal(err)
	}
	s.Close()

	s = openTestStore(t, path)
	n, err := s.Create(ctx, Input{Title: "again", Tags: []string{}})
	if err != nil {
		t.Fatal(err)
	}
	if n.ID != 3 {
		t.Fatalf("id = %d, want 3", n.ID)
	}
	if _, err := s.Get(ctx, 2); !errors.Is(err, ErrNotFound) {
		t.Fatalf("get deleted: %v", err)
	}
	counts, err := s.TagCounts(ctx)
	if err != nil {
		t.Fatal(err)
	}
	if len(counts) != 1 || counts[0] != (TagCount{Tag: "a", Count: 1}) {
		t.Fatalf("counts = %+v", counts)
	}
}

func TestListFilters(t *testing.T) {
	ctx := context.Background()
	s := openTestStore(t, filepath.Join(t.TempDir(), "notes.db"))
	for _, in := range []Input{
		{Title: "Hello 100%", Tags: []string{"x"}},
		{Title: "other", Body: "say HeLLo_", Tags: []string{"x", "y"}},
		{Title: "Ünï", Body: "", Tags: []string{}},
	} {
		if _, err := s.Create(ctx, in); err != nil {
			t.Fatal(err)
		}
	}
	ids := func(f Filter) []int64 {
		t.Helper()
		if f.Limit == 0 {
			f.Limit = 100
		}
		list, err := s.List(ctx, f)
		if err != nil {
			t.Fatal(err)
		}
		var out []int64
		for _, n := range list {
			out = append(out, n.ID)
		}
		return out
	}
	check := func(name string, got []int64, want ...int64) {
		t.Helper()
		if len(got) != len(want) {
			t.Fatalf("%s: got %v, want %v", name, got, want)
		}
		for i := range got {
			if got[i] != want[i] {
				t.Fatalf("%s: got %v, want %v", name, got, want)
			}
		}
	}
	check("all", ids(Filter{}), 1, 2, 3)
	check("q", ids(Filter{Query: "hello"}), 1, 2)
	check("q percent literal", ids(Filter{Query: "0%"}), 1)
	check("q underscore literal", ids(Filter{Query: "o_"}), 2)
	check("q non-ascii case sensitive", ids(Filter{Query: "ü"}))
	check("tag", ids(Filter{Tag: "y"}), 2)
	check("tag and q", ids(Filter{Tag: "x", Query: "say"}), 2)
	check("after", ids(Filter{After: 1}), 2, 3)
	check("limit", ids(Filter{Limit: 1, After: 1}), 2)
}

func mkdirAll(dir string) error { return os.MkdirAll(dir, 0o755) }

// Package server exposes the notes store over HTTP.
package server

import (
	"encoding/json"
	"errors"
	"io"
	"log/slog"
	"maps"
	"net/http"
	"slices"
	"strconv"
	"strings"

	"notes/internal/notes"
)

const (
	maxBodyBytes = 16 << 20
	defaultLimit = 100
	maxLimit     = 100
)

// Server serves the notes HTTP API.
type Server struct {
	store *notes.Store
	log   *slog.Logger
	mux   *http.ServeMux
}

// New returns an http.Handler for the notes API backed by store.
func New(store *notes.Store, log *slog.Logger) *Server {
	s := &Server{store: store, log: log, mux: http.NewServeMux()}
	s.route("/health", map[string]http.HandlerFunc{http.MethodGet: s.health})
	s.route("/notes", map[string]http.HandlerFunc{
		http.MethodGet:  s.listNotes,
		http.MethodPost: s.createNote,
	})
	s.route("/notes/{id}", map[string]http.HandlerFunc{
		http.MethodGet:    s.getNote,
		http.MethodPut:    s.updateNote,
		http.MethodDelete: s.deleteNote,
	})
	s.route("/stats", map[string]http.HandlerFunc{http.MethodGet: s.stats})
	s.route("/tags", map[string]http.HandlerFunc{http.MethodGet: s.tags})
	s.mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		writeError(w, http.StatusNotFound, "not found")
	})
	return s
}

func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) { s.mux.ServeHTTP(w, r) }

// route registers per-method handlers for an exact path, answering other methods with 405
// and a JSON body (ServeMux's built-in 405 is plain text).
func (s *Server) route(pattern string, methods map[string]http.HandlerFunc) {
	allow := strings.Join(slices.Sorted(maps.Keys(methods)), ", ")
	if get, ok := methods[http.MethodGet]; ok {
		methods[http.MethodHead] = get
	}
	s.mux.HandleFunc(pattern, func(w http.ResponseWriter, r *http.Request) {
		h, ok := methods[r.Method]
		if !ok {
			w.Header().Set("Allow", allow)
			writeError(w, http.StatusMethodNotAllowed, "method not allowed")
			return
		}
		h(w, r)
	})
}

func (s *Server) health(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	io.WriteString(w, "ok")
}

func (s *Server) createNote(w http.ResponseWriter, r *http.Request) {
	in, ok := s.readInput(w, r)
	if !ok {
		return
	}
	n, err := s.store.Create(r.Context(), in)
	if err != nil {
		s.internalError(w, err)
		return
	}
	writeJSON(w, http.StatusCreated, n)
}

func (s *Server) getNote(w http.ResponseWriter, r *http.Request) {
	id, ok := noteID(w, r)
	if !ok {
		return
	}
	n, err := s.store.Get(r.Context(), id)
	if s.storeError(w, err) {
		return
	}
	writeJSON(w, http.StatusOK, n)
}

func (s *Server) updateNote(w http.ResponseWriter, r *http.Request) {
	id, ok := noteID(w, r)
	if !ok {
		return
	}
	in, ok := s.readInput(w, r)
	if !ok {
		return
	}
	n, err := s.store.Update(r.Context(), id, in)
	if s.storeError(w, err) {
		return
	}
	writeJSON(w, http.StatusOK, n)
}

func (s *Server) deleteNote(w http.ResponseWriter, r *http.Request) {
	id, ok := noteID(w, r)
	if !ok {
		return
	}
	if s.storeError(w, s.store.Delete(r.Context(), id)) {
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func (s *Server) listNotes(w http.ResponseWriter, r *http.Request) {
	q := r.URL.Query()
	f := notes.Filter{Tag: q.Get("tag"), Query: q.Get("q"), Limit: defaultLimit}
	if q.Has("limit") {
		n, err := strconv.Atoi(q.Get("limit"))
		if err != nil || n < 1 || n > maxLimit {
			writeError(w, http.StatusBadRequest, "limit must be an integer from 1 to 100")
			return
		}
		f.Limit = n
	}
	if q.Has("after") {
		n, err := strconv.ParseInt(q.Get("after"), 10, 64)
		if err != nil {
			writeError(w, http.StatusBadRequest, "after must be an integer")
			return
		}
		f.After = n
	}
	list, err := s.store.List(r.Context(), f)
	if err != nil {
		s.internalError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"notes": list})
}

func (s *Server) stats(w http.ResponseWriter, r *http.Request) {
	count, err := s.store.Count(r.Context())
	if err != nil {
		s.internalError(w, err)
		return
	}
	counts, err := s.store.TagCounts(r.Context())
	if err != nil {
		s.internalError(w, err)
		return
	}
	tags := make(map[string]int64, len(counts))
	for _, tc := range counts {
		tags[tc.Tag] = tc.Count
	}
	writeJSON(w, http.StatusOK, map[string]any{"notes": count, "tags": tags})
}

func (s *Server) tags(w http.ResponseWriter, r *http.Request) {
	counts, err := s.store.TagCounts(r.Context())
	if err != nil {
		s.internalError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"tags": counts})
}

// readInput reads and validates a note payload, writing a 400 response on failure.
func (s *Server) readInput(w http.ResponseWriter, r *http.Request) (notes.Input, bool) {
	data, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxBodyBytes))
	if err != nil {
		var tooLarge *http.MaxBytesError
		if errors.As(err, &tooLarge) {
			writeError(w, http.StatusRequestEntityTooLarge, "request body too large")
		} else {
			writeError(w, http.StatusBadRequest, "could not read request body")
		}
		return notes.Input{}, false
	}
	in, err := notes.ParseInput(data)
	if err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return notes.Input{}, false
	}
	return in, true
}

// noteID parses the {id} path segment; anything but a positive decimal integer is a 404.
func noteID(w http.ResponseWriter, r *http.Request) (int64, bool) {
	raw := r.PathValue("id")
	for i := 0; i < len(raw); i++ {
		if raw[i] < '0' || raw[i] > '9' {
			raw = ""
			break
		}
	}
	id, err := strconv.ParseInt(raw, 10, 64)
	if err != nil || id < 1 {
		writeError(w, http.StatusNotFound, "note not found")
		return 0, false
	}
	return id, true
}

// storeError writes a response for a non-nil store error and reports whether it did.
func (s *Server) storeError(w http.ResponseWriter, err error) bool {
	switch {
	case err == nil:
		return false
	case errors.Is(err, notes.ErrNotFound):
		writeError(w, http.StatusNotFound, "note not found")
	default:
		s.internalError(w, err)
	}
	return true
}

func (s *Server) internalError(w http.ResponseWriter, err error) {
	s.log.Error("request failed", "err", err)
	writeError(w, http.StatusInternalServerError, "internal server error")
}

func writeError(w http.ResponseWriter, status int, msg string) {
	writeJSON(w, status, map[string]string{"error": msg})
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	data, err := json.Marshal(v)
	if err != nil {
		http.Error(w, `{"error":"internal server error"}`, http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	w.Write(append(data, '\n'))
}

package server

import (
	"context"
	"encoding/json"
	"io"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"strings"
	"sync"
	"testing"

	"notes/internal/notes"
)

func newTestServer(t *testing.T) *httptest.Server {
	t.Helper()
	store, err := notes.Open(context.Background(), filepath.Join(t.TempDir(), "notes.db"))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { store.Close() })
	ts := httptest.NewServer(New(store, slog.New(slog.DiscardHandler)))
	t.Cleanup(ts.Close)
	return ts
}

func do(t *testing.T, ts *httptest.Server, method, path, body string) (int, string) {
	t.Helper()
	req, err := http.NewRequest(method, ts.URL+path, strings.NewReader(body))
	if err != nil {
		t.Fatal(err)
	}
	res, err := ts.Client().Do(req)
	if err != nil {
		t.Fatal(err)
	}
	defer res.Body.Close()
	data, err := io.ReadAll(res.Body)
	if err != nil {
		t.Fatal(err)
	}
	return res.StatusCode, strings.TrimSpace(string(data))
}

func TestStatusCodes(t *testing.T) {
	ts := newTestServer(t)
	steps := []struct {
		method, path, body string
		status             int
		resp               string
	}{
		{"GET", "/health", "", 200, "ok"},
		{"POST", "/health", "", 405, ""},
		{"POST", "/notes", `{"title":"a","tags":["y","x"]}`, 201, `{"id":1,"title":"a","body":"","tags":["x","y"]}`},
		{"POST", "/notes", `{"title":"b","tags":["x"]}`, 201, ""},
		{"POST", "/notes", `{"title":5}`, 400, ""},
		{"DELETE", "/notes", "", 405, ""},
		{"PATCH", "/notes/1", "", 405, ""},
		{"GET", "/notes/1", "", 200, `{"id":1,"title":"a","body":"","tags":["x","y"]}`},
		{"GET", "/notes/-1", "", 404, ""},
		{"GET", "/notes/+1", "", 404, ""},
		{"GET", "/notes/99999999999999999999", "", 404, ""},
		{"GET", "/notes/1/extra", "", 404, ""},
		{"GET", "/notes/", "", 404, ""},
		{"PUT", "/notes/1", `{"title":"z"}`, 200, `{"id":1,"title":"z","body":"","tags":[]}`},
		{"PUT", "/notes/9", `{"title":"z"}`, 404, ""},
		{"PUT", "/notes/1", `{"title":""}`, 400, ""},
		{"GET", "/tags", "", 200, `{"tags":[{"tag":"x","count":1}]}`},
		{"DELETE", "/notes/2", "", 204, ""},
		{"DELETE", "/notes/2", "", 404, ""},
		{"GET", "/stats", "", 200, `{"notes":1,"tags":{}}`},
		{"GET", "/notes?limit=abc", "", 400, ""},
		{"GET", "/notes?limit=", "", 400, ""},
		{"GET", "/notes?after=-5", "", 200, `{"notes":[{"id":1,"title":"z","body":"","tags":[]}]}`},
		{"GET", "/notes?after=1.5", "", 400, ""},
		{"GET", "/missing", "", 404, ""},
	}
	for _, s := range steps {
		status, body := do(t, ts, s.method, s.path, s.body)
		if status != s.status {
			t.Errorf("%s %s: status %d, want %d (body %s)", s.method, s.path, status, s.status, body)
		}
		if s.resp != "" && body != s.resp {
			t.Errorf("%s %s: body %s, want %s", s.method, s.path, body, s.resp)
		}
		if status >= 400 {
			var e struct{ Error string }
			if err := json.Unmarshal([]byte(body), &e); err != nil || e.Error == "" {
				t.Errorf("%s %s: error body %q is not {\"error\": ...}", s.method, s.path, body)
			}
		}
	}
}

func TestConcurrentCreates(t *testing.T) {
	ts := newTestServer(t)
	const n = 50
	var wg sync.WaitGroup
	for range n {
		wg.Go(func() {
			if status, body := do(t, ts, "POST", "/notes", `{"title":"t","tags":["c"]}`); status != 201 {
				t.Errorf("status %d: %s", status, body)
			}
		})
	}
	wg.Wait()
	if _, body := do(t, ts, "GET", "/stats", ""); body != `{"notes":50,"tags":{"c":50}}` {
		t.Fatalf("stats = %s", body)
	}
}

// Command app serves a small SQLite-backed notes store over HTTP.
//
// Usage: NOTES_DB=/path/to/notes.db app <port>
package main

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"syscall"
	"time"

	"notes/internal/notes"
	"notes/internal/server"
)

func main() {
	log := slog.New(slog.NewTextHandler(os.Stderr, nil))
	if err := run(log, os.Args[1:]); err != nil {
		log.Error("fatal", "err", err)
		os.Exit(1)
	}
}

func run(log *slog.Logger, args []string) error {
	if len(args) != 1 {
		return errors.New("usage: app <port>")
	}
	port, err := strconv.ParseUint(args[0], 10, 16)
	if err != nil {
		return fmt.Errorf("invalid port %q", args[0])
	}
	dbPath := os.Getenv("NOTES_DB")
	if dbPath == "" {
		return errors.New("NOTES_DB is not set")
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	store, err := notes.Open(ctx, dbPath)
	if err != nil {
		return err
	}
	defer store.Close()

	ln, err := net.Listen("tcp", net.JoinHostPort("127.0.0.1", strconv.FormatUint(port, 10)))
	if err != nil {
		return err
	}
	srv := &http.Server{
		Handler:           server.New(store, log),
		ReadHeaderTimeout: 10 * time.Second,
		ReadTimeout:       time.Minute,
		WriteTimeout:      time.Minute,
		IdleTimeout:       2 * time.Minute,
	}

	errc := make(chan error, 1)
	go func() { errc <- srv.Serve(ln) }()
	log.Info("listening", "addr", ln.Addr().String(), "db", dbPath)

	select {
	case err := <-errc:
		return err
	case <-ctx.Done():
	}
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	return srv.Shutdown(shutdownCtx)
}
